"""Grounding of the plan's object phrases at dispatch time (design plan 8, D4 addendum 3).

    grounder = make_grounder(world, search=make_search_stub(), operator=make_operator(), side="left")
    r = grounder["begin"](step)       # when a manipulation step starts
    while r["state"] == "asking": r = grounder["poll"]()      # a tick later, until the operator has answered
    r["state"]        "resolved" (r["resolved"] = {role: Entry}), "failed" (r["reason"]) or "asking" (the operator is being asked)

When a step starts (not when the plan is made, so a moved object is handled), each object phrase of the step is resolved against the world model (src/world_model.py). The matching is
deterministic, no LLM: the phrase lower-cased with articles removed; a phrase equal to one of an entry's own phrases matches that entry first; property words ("full", "empty", "hot") must hold for the entry; the last remaining word is the head noun and must be the
head (last word) of one of the entry's phrases; every other word must be a word of the entry (its phrases, its text properties). A phrase with no noun ("the full one") matches every entry whose
property words hold. Three results:
  * one match: the entry is the step's object for that role.
  * none: the search module is called (search(phrase, world) -> {"status": "found" | "not_found" | "not_implemented", "entries": [...]}); found entries are written into the world model and the
    phrase is resolved again; the stub returns "not_implemented" and the plan stops with "object not found, search not implemented: <phrase>"; the real search is item B8 of design plan 9.
  * several: for a place step, the candidates are first narrowed to the ones the manipulating hand holds. If several remain the operator is asked (the candidates are printed on the console, with
    their positions and properties, and shown in the viewer's status text; the operator answers with a number; the choice is logged). With no operator present (unattended runs, the default)
    the plan stops with "ambiguous reference: <phrase>" and the candidates.
Then the step's own checks: a pick needs a manipulated object that nothing holds, in a hand that holds nothing; a place needs the manipulated object to be the one in the manipulating hand
(the phrase must resolve to what the hand holds, or the step stops), and a destination.

The operator is a dict: {"present": bool, "ask": ask(phrase, candidates, kind="ambiguous") (shows the request; kind "failure" is the orchestrator's question after a failed step, whose candidates are the options
retry / skip / abort: src/orchestrator.py), "answer": answer() -> the chosen number (1 to len(candidates)) or None while nobody has answered}.
make_operator() gives an unattended one (present False). make_scripted_operator() answers from a list after some polls (tests, and a stand-in for the viewer keys, which are LATER).

Every decision goes to grounder["log"]: dicts with "kind" ("resolved", "search", "operator_asked", "operator_chose", "failed"), the phrase, and the candidates' ids.

Contents:
    tokens, resolve, make_search_stub, make_operator, make_scripted_operator, make_grounder.
"""

import re

ARTICLES = {"the", "a", "an", "this", "that", "these", "those", "some", "one", "ones", "it"}
PROPERTY_WORDS = {
    "full": lambda e: e.properties.get("contents", "empty") != "empty",
    "empty": lambda e: e.properties.get("contents", "empty") == "empty",
    "hot": lambda e: e.properties.get("hot") is True,
}


def tokens(phrase):
    """Splits a phrase into lower-case words.

    Args:
        phrase (str): For example "The glass beaker".

    Returns:
        list[str]: The words ("the", "glass", "beaker").
    """
    return re.findall(r"[a-z0-9]+", phrase.lower())


def resolve(world, phrase):
    """Matches a phrase against the world model's entries.

    Args:
        world (WorldModel): The knowledge base.
        phrase (str): The phrase from the plan.

    Returns:
        list[Entry]: The matching entries (see the module docstring for the rule), in the model's order.
    """
    toks = [t for t in tokens(phrase) if t not in ARTICLES]
    exact = [e for e in world.entries() if toks and any(tokens(ph) == toks for ph in e.phrases)]
    if exact:                                                      # a phrase that is one of the entry's own ("hot plate") is not split into a property word and a noun
        return exact
    props = [t for t in toks if t in PROPERTY_WORDS]
    nouns = [t for t in toks if t not in PROPERTY_WORDS]
    out = []
    for e in world.entries():
        if not all(PROPERTY_WORDS[p](e) for p in props):
            continue
        if nouns:
            words = e.words()
            if not any(tokens(ph)[-1] == nouns[-1] for ph in e.phrases) or not set(nouns[:-1]) <= words:
                continue
        out.append(e)
    return out


def make_search_stub():
    """Builds the search module's stand-in: it reports that search is not implemented.

    Returns:
        dict: {"name": "search stub", "search": search(phrase, world) -> {"status": "not_implemented", "entries": []}}.
    """
    return {"name": "search stub", "search": lambda phrase, world: {"status": "not_implemented", "entries": []}}


def make_operator(present=False):
    """Builds an operator that cannot answer (unattended runs).

    Args:
        present (bool): Whether an operator is there. Defaults to False.

    Returns:
        dict: See the module docstring; ask() only prints, answer() is always None.
    """
    def ask(phrase, candidates, kind="ambiguous"):
        text = "; ".join(f"{i + 1}) {c.describe()}" for i, c in enumerate(candidates))
        print(f"[operator] {phrase}: {text}" if kind == "failure" else f"[grounding] {phrase!r} is ambiguous; candidates: {text}")
    return {"name": "operator" if present else "no operator", "present": present, "ask": ask, "answer": lambda: None}


def make_scripted_operator(answers, polls=1):
    """Builds an operator that answers from a list, `polls` polls after each question (tests).

    Args:
        answers (list[int]): The numbers to answer, one per question, in order.
        polls (int): How many answer() calls return None before the answer. Defaults to 1.

    Returns:
        dict: See the module docstring, plus "asked": the list of (phrase, candidate ids) asked.
    """
    S = {"i": 0, "wait": 0, "open": False, "asked": []}
    base = make_operator(True)

    def ask(phrase, candidates, kind="ambiguous"):
        base["ask"](phrase, candidates, kind)
        S["asked"].append((phrase, [c.id for c in candidates]))
        S["open"], S["wait"] = True, polls

    def answer():
        if not S["open"]:
            return None
        if S["wait"] > 0:
            S["wait"] -= 1
            return None
        S["open"] = False
        S["i"] += 1
        return answers[S["i"] - 1]
    return {"name": "scripted operator", "present": True, "ask": ask, "answer": answer, "asked": S["asked"]}


def make_grounder(world, search=None, operator=None, side="left"):
    """Builds the grounding module.

    Args:
        world (WorldModel): The knowledge base (refreshed at every begin()).
        search (dict or None): The search module. Defaults to the stub.
        operator (dict or None): The operator. Defaults to none present.
        side (str): The manipulating hand, "left" or "right". Defaults to "left".

    Returns:
        dict: {"begin"(step) -> result, "poll"() -> result, "phase"() -> str (the viewer's text while asking), "log": list}. A result is {"state": "resolved", "resolved": {role: Entry}},
        {"state": "failed", "reason": str} or {"state": "asking", "phrase", "candidates"}.
    """
    search = search or make_search_stub()
    operator = operator or make_operator()
    log = []
    S = {"gen": None, "candidates": None, "phrase": None}

    def note(kind, **kw):
        log.append({"time": world.time, "kind": kind, **kw})

    def fail(reason, **kw):
        note("failed", reason=reason, **kw)
        return {"state": "failed", "reason": reason}

    def run(step):
        """Generator: yields ("ask", phrase, candidates) and receives the operator's number; returns the final result dict."""
        prim, resolved = step["primitive"], {}
        for o in step["objects"]:
            phrase, role = o["phrase"], o["role"]
            found = resolve(world, phrase)
            if not found:
                sr = search["search"](phrase, world)
                note("search", phrase=phrase, status=sr["status"])
                if sr["status"] == "not_implemented":
                    return fail(f"object not found, search not implemented: {phrase}", phrase=phrase)
                for e in sr["entries"]:
                    world.upsert(e)
                found = resolve(world, phrase)
                if not found:
                    return fail(f"object not found: {phrase}", phrase=phrase)
            if len(found) > 1 and prim == "place" and role == "manipulated":
                held = [e for e in found if e.properties.get("held_by") == side]
                if held:
                    found = held
            if len(found) > 1:
                if not operator["present"]:
                    return fail(f"ambiguous reference: {phrase!r}; candidates: " + "; ".join(e.describe() for e in found), phrase=phrase, candidates=[e.id for e in found])
                note("operator_asked", phrase=phrase, candidates=[e.id for e in found])
                n = yield ("ask", phrase, found)
                if not isinstance(n, int) or not 1 <= n <= len(found):
                    return fail(f"the operator's answer {n!r} is not one of 1 to {len(found)} for {phrase!r}", phrase=phrase)
                found = [found[n - 1]]
                note("operator_chose", phrase=phrase, chosen=found[0].id, number=n)
            resolved[role] = found[0]
            note("resolved", phrase=phrase, role=role, entry=found[0].id)
        man, dest = resolved.get("manipulated"), resolved.get("destination")
        if prim == "pick":
            if man is None:
                return fail("the pick step names no object to pick up")
            if man.properties.get("held_by") is not None:
                return fail(f"{man.id} is already held by the {man.properties['held_by']} hand")
            hand = world.held_by(side)
            if hand:
                return fail(f"the {side} hand is not empty: it holds {', '.join(e.id for e in hand)}")
        elif prim == "place":
            if man is None or dest is None:
                return fail("the place step needs an object (manipulated) and a surface (destination)")
            if man.properties.get("held_by") != side:
                hand = world.held_by(side)
                return fail(f"the object to place ({man.id}) is not the one in the {side} hand (the hand holds {', '.join(e.id for e in hand) if hand else 'nothing'})")
        return {"state": "resolved", "resolved": resolved}

    def advance(value=None):
        try:
            kind, phrase, cands = S["gen"].send(value) if value is not None else next(S["gen"])
        except StopIteration as stop:
            S["gen"] = None
            return stop.value
        S["phrase"], S["candidates"] = phrase, cands
        operator["ask"](phrase, cands)
        return {"state": "asking", "phrase": phrase, "candidates": cands}

    def begin(step):
        world.refresh()
        S["gen"] = run(step)
        return advance()

    def poll():
        if S["gen"] is None:
            return {"state": "failed", "reason": "no grounding in progress"}
        n = operator["answer"]()
        if n is None:
            return {"state": "asking", "phrase": S["phrase"], "candidates": S["candidates"]}
        return advance(n)

    def phase():
        if S["gen"] is None:
            return "GROUNDING"
        return f"ASK OPERATOR {S['phrase']!r}: " + "; ".join(f"{i + 1}) {c.describe()}" for i, c in enumerate(S["candidates"]))

    return {"name": "grounding", "begin": begin, "poll": poll, "phase": phase, "log": log}
